  3	/**
  4	 * @file serve_spec_lookup.c
  5	 * @brief Prompt-lookup drafts for the serve's speculative decode. See serve_spec_lookup.h.
  6	 *
  7	 * @status Working off-hardware (tests/test_serve_spec_lookup.c).
  8	 * @issues None
  9	 * @todo None
 10	 */
 11	
 12	#include "serve_spec_lookup.h"
 13	
 14	#include <stdio.h>
 15	#include <stdlib.h>
 16	#include <string.h>
 17	
 18	/** Longest suffix tried first (higher precision). */
 19	#define LOOKUP_NGRAM_MAX 6
 20	
 21	/** The throttle: a lookup cycle accepting fewer drafts than this is a miss; after this many
 22	 *  misses in a row lookup rests for this many cycles (the MTP head drafts meanwhile). */
 23	#define LOOKUP_MIN_ACCEPT 3
 24	#define LOOKUP_MISS_LIMIT 2
 25	#define LOOKUP_COOL_CYCLES 16
 26	
 27	static int lookup_env(const char *name, int fallback)
 28	{
 29	    const char *value = getenv(name);
 30	
 31	    return value && *value ? atoi(value) : fallback;
 32	}
 33	
 34	int sg_spec_lookup_init(sg_spec_lookup *lookup, const uint32_t *prompt, int n_prompt,
 35	                        int max_new)
 36	{
 37	    memset(lookup, 0, sizeof(*lookup));
 38	    lookup->mode = lookup_env("PN_TT_SPEC_LOOKUP", 2);
 39	    if (lookup->mode <= 0 || !prompt || n_prompt < 0 || max_new < 0)
 40	        return 0;
 41	    lookup->k = lookup_env("PN_TT_SPEC_LOOKUP_K", 6);
 42	    lookup->min_ngram = lookup_env("PN_TT_SPEC_LOOKUP_MIN", 3);
 43	    if (lookup->k < 1 || lookup->min_ngram < 1)
 44	        return 0;
 45	    if (lookup->k > 15)
 46	        lookup->k = 15;
 47	    lookup->capacity = n_prompt + max_new + 16;
 48	    lookup->history = malloc((size_t)lookup->capacity * sizeof(*lookup->history));
 49	    if (!lookup->history)
 50	        return -1;
 51	    memcpy(lookup->history, prompt, (size_t)n_prompt * sizeof(*prompt));
 52	    lookup->count = n_prompt;
 53	    pn_spec_throttle_init(&lookup->throttle, LOOKUP_MIN_ACCEPT, LOOKUP_MISS_LIMIT,
 54	                          LOOKUP_COOL_CYCLES);
 55	    lookup->on = true;
 56	    return 0;
 57	}
 58	
 59	bool sg_spec_lookup_agrees(const sg_spec_lookup *lookup, uint32_t looked_first,
 60	                           uint32_t mtp_first)
 61	{
 62	    return lookup->mode != 2 || looked_first == mtp_first;
 63	}
 64	
 65	void sg_spec_lookup_push(sg_spec_lookup *lookup, uint32_t token)
 66	{
 67	    if (!lookup->on)
 68	        return;
 69	    if (lookup->count == lookup->capacity) {
 70	        uint32_t *grown = realloc(lookup->history,
 71	                                  (size_t)lookup->capacity * 2u * sizeof(*grown));
 72	
 73	        if (!grown) {
 74	            lookup->on = false;
 75	            return;
 76	        }
 77	        lookup->history = grown;
 78	        lookup->capacity *= 2;
 79	    }
 80	    lookup->history[lookup->count++] = token;
 81	}
 82	
 83	int sg_spec_lookup_draft(sg_spec_lookup *lookup, int cap, uint32_t *drafts)
 84	{
 85	    const int want = cap < lookup->k ? cap : lookup->k;
 86	    const int longest = LOOKUP_NGRAM_MAX > lookup->min_ngram ? LOOKUP_NGRAM_MAX
 87	                                                             : lookup->min_ngram;
 88	
 89	    if (!lookup->on || want < 1 || !pn_spec_throttle_gate(&lookup->throttle))
 90	        return 0;
 91	    return pn_ngram_draft(lookup->history, lookup->count, longest, lookup->min_ngram, want,
 92	                          drafts);
 93	}
 94	
 95	void sg_spec_lookup_report(sg_spec_lookup *lookup, int drafted, int accepted)
 96	{
 97	    lookup->cycles++;
 98	    lookup->drafted += (uint64_t)drafted;
 99	    lookup->accepted += (uint64_t)accepted;
100	    pn_spec_throttle_report(&lookup->throttle, accepted);
101	}
102	
103	void sg_spec_lookup_free(sg_spec_lookup *lookup)
104	{
105	    if (lookup->cycles)
106	        fprintf(stderr, "serve: LOOKUP — %llu cycles, %llu drafted, %llu accepted (%.2f)\n",
107	                (unsigned long long)lookup->cycles, (unsigned long long)lookup->drafted,
108	                (unsigned long long)lookup->accepted,
109	                lookup->drafted ? (double)lookup->accepted / (double)lookup->drafted : 0.0);
110	    free(lookup->history);
111	    memset(lookup, 0, sizeof(*lookup));
112	}
